/**
 * A deliberately small Markdown subset rendered to React nodes.
 *
 * Why not a Markdown library: every mainstream renderer produces an HTML string
 * that has to be trusted or sanitized, and this view shows text generated by a
 * remote model. Building React elements instead means untrusted text can only
 * ever become text — there is no `innerHTML` here, so raw HTML in a reply is
 * displayed literally rather than parsed.
 *
 * Supported: **bold**, *italic*, `code`, headings, bullet and numbered lists,
 * blockquotes, horizontal rules, and [label](url) links restricted to http(s).
 * Everything else, including tables, images, and raw HTML, stays literal text.
 */

import { type ReactNode } from "react";

import { api } from "../../lib/ipc/client";

const ALLOWED_LINK = /^https?:\/\//i;

/** Only http(s) links pass; credentials in the URL are rejected. */
export function safeHref(raw: string): string | null {
  const trimmed = raw.trim();
  if (!ALLOWED_LINK.test(trimmed)) return null;
  try {
    const url = new URL(trimmed);
    if (!["http:", "https:"].includes(url.protocol)) return null;
    if (url.username || url.password) return null;
    return url.href;
  } catch {
    return null;
  }
}

/**
 * Inline spans for one line of text. Unmatched or nested-by-one-character
 * delimiters degrade to literal text rather than swallowing the rest of a reply:
 * an unterminated `**` is common in a cancelled answer.
 */
function inline(text: string, keyPrefix: string): ReactNode[] {
  const out: ReactNode[] = [];
  let index = 0;

  const pushText = (value: string) => {
    if (value) out.push(value);
  };

  while (index < text.length) {
    const rest = text.slice(index);
    // Code first: its contents must never be interpreted as bold or links.
    const code = /^`([^`\n]+)`/.exec(rest);
    if (code) {
      out.push(
        <code key={`${keyPrefix}-c${index}`} className="md-code">
          {code[1] ?? ""}
        </code>,
      );
      index += code[0].length;
      continue;
    }
    const link = /^\[([^\]\n]+)\]\(([^)\s]+)\)/.exec(rest);
    if (link) {
      const href = safeHref(link[2] ?? "");
      if (href) {
        // A button, not an anchor: the URL comes from a model reply, so it goes
        // through Rust's scheme allowlist instead of into an href the webview can
        // navigate to. `target="_blank"` is also a no-op in Android WebView, where
        // an anchor would replace the app in place.
        out.push(
          <button
            key={`${keyPrefix}-a${index}`}
            type="button"
            className="linkbtn"
            onClick={() => {
              void api.openExternal(href).catch(() => undefined);
            }}
          >
            {inline(link[1] ?? "", `${keyPrefix}-a${index}`)}
          </button>,
        );
        index += link[0].length;
        continue;
      }
      // Not a safe link: fall through so it renders as the literal source.
    }
    const bold = /^\*\*([^*\n]+(?:\*[^*\n]+)*)\*\*/.exec(rest);
    if (bold) {
      out.push(
        <strong key={`${keyPrefix}-b${index}`}>
          {inline(bold[1] ?? "", `${keyPrefix}-b${index}`)}
        </strong>,
      );
      index += bold[0].length;
      continue;
    }
    const italic = /^\*([^*\n]+)\*|^_([^_\n]+)_/.exec(rest);
    if (italic) {
      out.push(
        <em key={`${keyPrefix}-i${index}`}>
          {inline(italic[1] ?? italic[2] ?? "", `${keyPrefix}-i${index}`)}
        </em>,
      );
      index += italic[0].length;
      continue;
    }
    pushText(text[index] ?? "");
    index += 1;
  }
  return out;
}

const BULLET = /^\s{0,3}[-*+]\s+(.*)$/;
const NUMBERED = /^\s{0,3}(\d{1,3})[.)]\s+(.*)$/;
const HEADING = /^\s{0,3}(#{1,4})\s+(.*)$/;
const RULE = /^\s{0,3}(?:-{3,}|\*{3,}|_{3,})\s*$/;

export function renderMarkdown(source: string): ReactNode {
  if (!source) return null;
  const lines = source.replace(/\r\n?/g, "\n").split("\n");
  const blocks: ReactNode[] = [];
  let paragraph: string[] = [];
  let index = 0;

  const flush = () => {
    if (!paragraph.length) return;
    const key = `p${blocks.length}`;
    blocks.push(
      <p key={key} className="md-p">
        {inline(paragraph.join(" "), key)}
      </p>,
    );
    paragraph = [];
  };

  while (index < lines.length) {
    const line = lines[index] ?? "";
    if (!line.trim()) {
      flush();
      index += 1;
      continue;
    }
    if (RULE.test(line)) {
      flush();
      blocks.push(<hr key={`hr${blocks.length}`} className="md-hr" />);
      index += 1;
      continue;
    }
    const heading = HEADING.exec(line);
    if (heading) {
      flush();
      const level = Math.min((heading[1] ?? "#").length + 2, 4);
      const Tag = `h${level}` as "h3" | "h4" | "h5" | "h6";
      blocks.push(
        <Tag key={`h${blocks.length}`} className={`md-h${level}`}>
          {inline(heading[2] ?? "", `h${blocks.length}`)}
        </Tag>,
      );
      index += 1;
      continue;
    }
    if (BULLET.test(line) || NUMBERED.test(line)) {
      flush();
      const ordered = !BULLET.test(line);
      const items: string[] = [];
      let start = 1;
      while (index < lines.length) {
        const current = lines[index] ?? "";
        const bullet = BULLET.exec(current);
        const numbered = NUMBERED.exec(current);
        if (bullet) items.push(bullet[1] ?? "");
        else if (numbered) {
          if (items.length === 0) start = Number(numbered[1]);
          items.push(numbered[2] ?? "");
        } else break;
        index += 1;
      }
      const key = `l${blocks.length}`;
      const children = items.map((item, position) => (
        <li key={`${key}-${position}`}>{inline(item, `${key}-${position}`)}</li>
      ));
      blocks.push(
        ordered ? (
          <ol key={key} className="md-list" start={start}>
            {children}
          </ol>
        ) : (
          <ul key={key} className="md-list">
            {children}
          </ul>
        ),
      );
      continue;
    }
    const quote = /^\s{0,3}>\s?(.*)$/.exec(line);
    if (quote) {
      flush();
      const quoted: string[] = [];
      while (index < lines.length) {
        const next = /^\s{0,3}>\s?(.*)$/.exec(lines[index] ?? "");
        if (!next) break;
        quoted.push(next[1] ?? "");
        index += 1;
      }
      const key = `q${blocks.length}`;
      blocks.push(
        <blockquote key={key} className="md-quote">
          {quoted.map((text, position) => (
            <p key={`${key}-${position}`} className="md-p">
              {inline(text, `${key}-${position}`)}
            </p>
          ))}
        </blockquote>,
      );
      continue;
    }
    paragraph.push(line.trim());
    index += 1;
  }
  flush();
  return blocks;
}
